    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日日历事件列表，卡片展示第一条需要关注的日程。",
          "sampleValue": [
            {
              "entityId": "calendar-urgent-001",
              "title": "线上发布会",
              "dtStart": "14:00",
              "dtEnd": "15:00",
              "eventLocation": "会议室A",
              "importantEventType": 2
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日历事件。",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符。",
                "sampleValue": "calendar-urgent-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "线上发布会"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程使用 HH:MM 展示。",
                "sampleValue": "14:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程使用 HH:MM 展示。",
                "sampleValue": "15:00"
              },
              "eventLocation": {
                "type": "string",
                "description": "日程发生地点。",
                "sampleValue": "会议室A"
              },
              "importantEventType": {
                "type": "integer",
                "description": "日程重要类型，2 表示紧急或倒数类重要日程。",
                "sampleValue": 2
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": []
}

